def safe_execute_code(code):
    # Parse the code to an AST and check for potentially dangerous nodes
    try:
        tree = ast.parse(code)
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom, ast.Exec, ast.FunctionDef, ast.ClassDef)):
                raise ValueError("Code contains potentially dangerous constructs.")
    except SyntaxError:
        raise ValueError("Invalid code syntax.")

