import os

def secure_file_access(file_path):
    # Normalize the file path to prevent path traversal attacks
    normalized_path = os.path.normpath(file_path)

    # Get the absolute path of the file
    absolute_path = os.path.abspath(normalized_path)

    # Check if the file is within the expected directory
    expected_dir = '/expected/directory'
    if not absolute_path.startswith(expected_dir):
        raise ValueError("File access denied due to security restrictions")

    # If the file is within the expected directory, proceed with file access
    try:
        with open(absolute_path, 'r') as file:
            return file.read()
    except FileNotFoundError:
        return None

